"""Version history for the mirror.

Each time the mirror changes, a snapshot records which file contents it held.
File contents are stored once, by hash, so unchanged files cost nothing.
"""
from __future__ import annotations

import hashlib
import json
import shutil
from datetime import datetime, timezone
from pathlib import Path


def root() -> Path:
    return Path.home() / "openmarker" / "history"


def _blob(digest: str) -> Path:
    return root() / "blobs" / digest[:2] / digest


def _tracked(path: str) -> bool:
    # Thumbnails are regenerated by the tablet; its sync cache is not content.
    return ".thumbnails/" not in path and path != ".tree" and not path.endswith(".local")


def snapshots() -> list[Path]:
    return sorted((root() / "snapshots").glob("*.json"))


def read(snapshot: Path) -> dict[str, str]:
    return json.loads(snapshot.read_text(encoding="utf-8"))


def record(mirror: Path, hashes: dict[str, str]) -> Path | None:
    """Snapshot the mirror if it differs from the last snapshot."""
    manifest = {p: d for p, d in sorted(hashes.items()) if _tracked(p)}
    existing = snapshots()
    if existing and read(existing[-1]) == manifest:
        return None
    for path, digest in manifest.items():
        blob = _blob(digest)
        if not blob.exists():
            blob.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(mirror / path, blob)
            if hashlib.sha256(blob.read_bytes()).hexdigest() != digest:
                blob.unlink()
                raise RuntimeError(f"mirror file changed while snapshotting: {path}")
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    target = root() / "snapshots" / f"{stamp}.json"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(manifest, indent=0), encoding="utf-8")
    return target


def _when(snapshot: Path) -> str:
    return datetime.strptime(snapshot.stem, "%Y%m%dT%H%M%S%fZ").replace(tzinfo=timezone.utc).isoformat()


def _doc_files(manifest: dict[str, str], doc: str) -> dict[str, str]:
    return {p: d for p, d in manifest.items() if p.startswith(f"{doc}.") or p.startswith(f"{doc}/")}


def versions(doc: str) -> list[dict]:
    """Snapshots in which the document differs from the previous one, oldest first."""
    out, previous = [], None
    for snapshot in snapshots():
        files = _doc_files(read(snapshot), doc)
        if files and files != previous:
            changed = sorted(
                p.split("/")[1][:-3]
                for p, d in files.items()
                if p.endswith(".rm") and (previous or {}).get(p) != d
            )
            out.append({"id": snapshot.stem, "when": _when(snapshot), "changed_pages": changed})
        if files:
            previous = files
    return out


def files_at(doc: str, snapshot_id: str) -> dict[str, Path]:
    """Store-relative path -> stored blob, for one document in one snapshot."""
    snapshot = root() / "snapshots" / f"{snapshot_id}.json"
    return {p: _blob(d) for p, d in _doc_files(read(snapshot), doc).items()}
